import * as alien from "@alienplatform/core"

const api = new alien.Container("api")
  .code({ type: "image", image: "ghcr.io/acme/api:1.0.0" })
  .cpu(1)
  .memory("1Gi")
  .port(8080)
  .permissions("api")
  .build()

const tools = new alien.Container("tools")
  .code({ type: "image", image: "ghcr.io/acme/tools:1.0.0" })
  .cpu(1)
  .memory("1Gi")
  .port(9090)
  .permissions("tools")
  .build()

const runner = new alien.Sandbox("runner")
  .code({ type: "image", image: "s3://acme-bundles/runner/{region}/rootfs.tar" })
  .egress("internet")
  .defaultPolicy({ allow: ["link:api"] })
  .lifecycle({})
  .link(api)
  .link(tools)
  .build()

export default new alien.Stack("acme-sandbox-links")
  .platforms(["aws", "kubernetes"])
  .add(runner, "live")
  .add(api, "live")
  .add(tools, "live")
  .permissions({ profiles: { api: {}, tools: {} } })
  .build()
